import click
from click.testing import CliRunner
r = CliRunner()

def show(name, cmd, args=(), dm=None):
    res = r.invoke(cmd, list(args), default_map=dm)
    print(f"{name}: dm={dm} args={args} -> {res.exit_code} {res.output!r} {res.exception}")

@click.command()
@click.option("--flag/--no-flag", default=True)
def c1(flag):
    click.echo(f"flag={flag}")
show("boolflag default True", c1, [], {"flag": False})
show("boolflag default True", c1, [], {"flag": True})
