import click
from click.testing import CliRunner
r = CliRunner()

def mk(**kw):
    @click.command()
    @click.option("--flag", **kw)
    def cli(flag):
        click.echo(f"flag={flag!r}")
    return cli

for kw in [dict(is_flag=True), dict(is_flag=True, default=False), dict(is_flag=True, default=True),
           dict(is_flag=False), dict(default=False), dict(default=True)]:
    cmd = mk(**kw)
    for dm in [None, {"flag": True}, {"flag": False}]:
        res = r.invoke(cmd, [], default_map=dm)
        print(kw, dm, "->", res.exit_code, repr(res.output), res.exception)
    print()
