import marshal, dis, io, os, sys
d='src/click/__pycache__'
for f in sorted(os.listdir(d)):
    if not f.endswith('.pyc'): continue
    mod=f.split('.')[0]
    src=f'src/click/{mod}.py'
    if not os.path.exists(src): continue
    pyc=open(os.path.join(d,f),'rb').read()
    try:
        c1=marshal.loads(pyc[16:])
    except Exception as e:
        print(f, 'ERR', e); continue
    c2=compile(open(src).read(), c1.co_filename, 'exec')
    def dump(c):
        out=io.StringIO()
        def rec(co, ind=0):
            out.write(' '*ind+co.co_name+'\n')
            for const in co.co_consts:
                if hasattr(const,'co_name'):
                    rec(const, ind+2)
        rec(c)
        return out.getvalue()
    same = dump(c1)==dump(c2)
    print(f, 'structure-same' if same else 'STRUCTURE DIFF')
